"""The proposals document must contain the tables the script produces (it is regenerated by hand from `rubric_proposals.py --tables`)."""
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import rubric_proposals as R  # noqa: E402

REPO = R.REPO


# ------------------------------------------------------------------------------------------------ the document is current
def test_proposals_document_contains_every_table_the_script_produces():
    doc = open(os.path.join(REPO, "docs", "brains", "LAKE_BRAIN_RUBRIC_PROPOSALS.md")).read()
    tables = R.render_tables()
    shown = ["dims", "mean_stack", "classification", "p1", "p3", "combined", "claims196", "claims_fleets", "max_63_KNOWN", "max_63_CEILING", "max_196_KNOWN",
             "max_196_CEILING", "max_427_KNOWN", "max_427_CEILING", "maxPA_196_CEILING", "first_n", "order", "margin", "headroom"]
    for k in shown:
        assert tables[k] in doc, f"table {k} in docs/brains/LAKE_BRAIN_RUBRIC_PROPOSALS.md is stale: re-run rubric_proposals.py --tables"
    for name in ("P1-X", "P2", "P3-X"):
        assert json.dumps(R.PATCHES[name], indent=1) in doc, name
    # headline claims quoted in prose
    assert "3.0 / 10, uncapped 6.3" in doc and "8.045" in doc and "**156 = 25 % of 621**" in doc
